const original = $items('Workflow Input')[0].json;
const memories = $json.matches || [];
const memoryContext = JSON.stringify(memories).slice(0, 2500);
const facts = `Person: ${original.contact_name || ''}
Company: ${original.company || ''}
Opportunity: ${original.opportunity || ''}
Relationship context: ${original.relationship_context || ''}
Ask context: ${original.ask_context || ''}
Retrieved context: ${memoryContext}`;
const guardrail = 'Use only the supplied facts. Never invent a relationship, shared experience, metric, credential, or referral.';
return [{ json: { ...original, retrieved_memory: memories, subject_prompt: `${guardrail} Return only a personal subject line, at most 7 words. No label or quotation marks.

${facts}`, opening_prompt: `${guardrail} Return only one warm opening sentence, at most 16 words. Do not use a greeting, sign-off, or label.

${facts}`, context_prompt: `${guardrail} Return one concrete relationship or opportunity sentence, at most 18 words. If unsupported, return exactly NONE. No label.

${facts}`, ask_prompt: `${guardrail} Return only one concise, no-pressure referral question, at most 18 words. No greeting, sign-off, or label.

${facts}` } }];

const context = $items('Build Referral Email Prompts')[0].json;
const clean = (value) => String(value || '')
  .replace(/<think>[\s\S]*?<\/think>/gi, '')
  .replace(/^(subject|opening|relationship point|referral ask)\s*:\s*/i, '')
  .replace(/^[\"'`]+|[\"'`]+$/g, '')
  .replace(/\s+/g, ' ')
  .trim();
const subject = clean($items('Draft Referral Subject')[0].json.response) || 'Quick referral question';
const opening = clean($items('Draft Referral Opening')[0].json.response) || 'I hope you are doing well.';
const relationshipPoint = clean($items('Draft Relationship Point')[0].json.response);
const ask = clean($items('Draft Referral Ask')[0].json.response) || 'Would you be comfortable referring me if it feels appropriate?';
const firstName = String(context.contact_name || '').trim().split(/\s+/)[0];
const greeting = firstName ? `Hi ${firstName},` : 'Hello,';
const hasRelationshipPoint = relationshipPoint && !/^(none|n\/a|no relationship point)\.?$/i.test(relationshipPoint);
const draftBody = [greeting, opening, hasRelationshipPoint ? relationshipPoint : '', ask, 'Best,\nPruthvi Kadam'].filter(Boolean).join('\n\n');
return [{ json: { ...context, draft_subject: subject, draft_body: draftBody, draft_reasoning: 'Fixed boilerplate with concise AI-generated subject, opening, optional relationship point, and referral ask.' } }];
